shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('build/utilityclass-repro')
p.mkdir(exist_ok=True)
(p / 'Converter.java').write_text('''import lombok.experimental.UtilityClass;

@UtilityClass
class Converter {
    <T> T convertValue(Class<T> toValueType) {
        return null;
    }

    DTO convert(Object json) {
        return convertValue(DTO.class);
    }

    Object convert(DTO dto) {
        return null;
    }

    class DTO {
    }
}
''')
(p / 'attach.json').write_text('''{"port": 5005, "sources": ["../../src/core/lombok/javac/handlers/HandleUtilityClass.java"], "class_roots": ["../lombok-main"]}\n''')
PY
javac -cp build/lombok-main:build/lombok-utils:build/lombok-utils6:build/lombok-main8 -d build/utilityclass-repro build/utilityclass-repro/Converter.java

cd /testbed && grep -i -n -m1 '^//.*platform.*javac' test/transform/resource/before/*.java | head -12 && python3 - <<'PY'
from pathlib import Path
p = Path('test/transform/resource/before/UtilityClassGeneric.java')
assert not p.exists()
p.write_text('''@lombok.experimental.UtilityClass
class UtilityClassGeneric {
	<T> T convertValue(Class<T> toValueType) {
		return null;
	}

	DTO convert(Object json) {
		return convertValue(DTO.class);
	}

	Object convert(DTO dto) {
		return null;
	}

	class DTO {
	}
}
''')
p = Path('test/transform/resource/after-delombok/UtilityClassGeneric.java')
assert not p.exists()
p.write_text('''final class UtilityClassGeneric {
	static <T> T convertValue(Class<T> toValueType) {
		return null;
	}
	static DTO convert(Object json) {
		return convertValue(DTO.class);
	}
	static Object convert(DTO dto) {
		return null;
	}
	static class DTO {
	}
	@java.lang.SuppressWarnings("all")
	private UtilityClassGeneric() {
		throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
	}
}
''')
p = Path('test/transform/resource/after-ecj/UtilityClassGeneric.java')
assert not p.exists()
p.write_text('''final @lombok.experimental.UtilityClass class UtilityClassGeneric {
  static class DTO {
    DTO() {
      super();
    }
  }
  static <T>T convertValue(Class<T> toValueType) {
    return null;
  }
  static DTO convert(Object json) {
    return convertValue(DTO.class);
  }
  static Object convert(DTO dto) {
    return null;
  }
  private @java.lang.SuppressWarnings("all") UtilityClassGeneric() {
    super();
    throw new java.lang.UnsupportedOperationException("This is a utility class and cannot be instantiated");
  }
}
''')
p = Path('doc/changelog.markdown')
s = p.read_text()
old = '* No new changes since the release of v1.18.24'
assert s.count(old) == 1
p.write_text(s.replace(old, '* BUGFIX: `@UtilityClass` no longer causes javac to crash when generic calls use nested classes alongside overloaded methods.'))
PY
ant -quiet test.javacCurrent > build/utilityclass-repro/javac-tests.log 2>&1; result=$?; tail -35 build/utilityclass-repro/javac-tests.log; exit "$result"

